def quote_skew_tax(gross_cents: int = 990) -> dict:
    net_base = (gross_cents * 10) // 11
    tax = (net_base * 10) // 100
    b = -10
    alpha = 0
    return {
        'tax_reserve_cents': tax,
        'tax_alpha': alpha,
        'residual_2': b + 2 * alpha,
    }

